insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-42932','course','🚀Введение в должность Менеджера «Бара 90-е»',null,'{"id":"guru-42932","title":"🚀Введение в должность Менеджера «Бара 90-е»","shortTitle":"🚀Введение в должность Менеджера «Бара 90-е»","coverLabel":"🚀Введение в должность Менеджера «Бара 90-е»","description":"Стажировка менеджера: команда, хостес, касса, управление сменой, аттестация и KPI.","kind":"course","brand":"90-е","departments":["Руководитель","Зал","Бар"],"positions":["Руководитель","Администратор","Старший бармен"],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"🎓КЛН МЕНЕДЖЕРА — Контрольный лист наблюдения","text":"Цель: понять, по каким критериям оценивается работа менеджера, и к чему стремиться.\n\n📋 Что такое КЛН\n\nКЛН (Контрольный лист наблюдения) — это свод стандартов, по которым оценивается работа менеджера. Это твой навигатор в мире профессионального управления.\n\nЗачем он нужен:\n\nТы видишь чёткие критерии оценки.\nПонимаешь, на что обращают внимание управляющий и наставник.\nМожешь самостоятельно оценивать свой прогресс.\nЗнаешь, к чему стремиться.\n\nСКАЧАЙ КЛН\n\n⭐ Как оцениваются критерии\n\nКаждый пункт оценивается по простой шкале:\n\nВыполнено: Соответствует стандарту, всё сделано правильно\nЧастично: Есть мелкие недочёты, но в целом выполнено\nНе выполнено: Не сделано или выполнено с грубыми ошибками\n\n85% — минимальный процент выполнения для успешного прохождения аттестации.\n\n100%: Отлично! Ты готов к самостоятельной работе\n85% и выше: Проходной балл, ты справляешься со стандартами\nНиже 85%: Нужно доработать. На KPI пока не рассчитывай, требуется дополнительное обучение\n📝 Полный список критериев КЛН менеджера\n\n1️⃣ Работа с персоналом и готовность зала\n\n1.1. Все сотрудники прибыли вовремя на работу.\n1.2. Внешний вид персонала соответствует стилю 90-х.\n1.3. Проведено собрание с персоналом в 17:45 (озвучены все насущные вопросы: отзывы, конкурс, итд). Напоминание про карту лояльности: перед расчётом официант уточняет, зарегистрирован ли гость в системе лояльности. Если да — берёт номер карты, если нет — регистрирует.\n1.4. Все сотрудники знают актуальные акции и предложения.\n1.5. Проведена проверка знаний акций и будущих мероприятий.\n1.6. Проверена чистота входной зоны.\n1.7. Все туалеты чистые (унитазы, раковины, зеркала, расходники пополнены).\n1.8. Протёрт весь декор (пыль, чистота фигур, фотозон и пр.).\n1.9. Чистота барной стойки проверена, маркировка продукции актуальна.\n1.10. Полностью готово заведение к открытию (чистота зала, столов, мебели).\n1.11. Освещение и звук входной группы исправны и работают в штатном режиме в 17:50 включено.\n1.12. Освещение залов работает корректно согласно времени суток.\n\n2️⃣ Работа с таблицами бронирования/заявок/предоплат\n\n2.1. Разобраны все входящие заявки по броням.\n2.2. Проведена актуализация всех броней (связались с гостями, подтвердили).\n2.3. Все брони подтверждены (гости внесли предоплату).\n2.4. Неподтверждённые брони: указана причина и снесены в отмены.\n2.5. Сделаны предзаказы по мероприятиям для компаний от 6 человек.\n2.6. Предзаказы отмечены в таблице бронирования.\n2.7. Предзаказы переданы на кухню (шеф поставлен в известность).\n2.8. Предзаказы отправлены в рабочий чат «Предзаказы».\n2.9. Сверены все предоплаты с отметками в таблицах бронирования и предоплат.\n2.10. Предоплаты по Eat&Split внесены в систему iiko.\n\n3️⃣ Документооборот и отчёты\n\n3.1. В сводной таблице по поиску персонала заведены все комментарии по кандидатам, записанным на собеседование.\n3.2. В таблице «Персонал» все сотрудники действующие.\n3.3. У всех действующих сотрудников актуальные медицинские книжки.\n3.4. В чат «Штат» отправлены дни рождения сотрудников следующего месяца (раз в месяц, 28 числа).\n\n4️⃣ Склад, хозчасть и чистота заведения\n\n4.1. Проверено наличие всех необходимых хозяйственных товаров (хозы).\n4.2. Заказаны недостающие хозтовары (идентичны предыдущим заказам).\n4.3. Всё оборудование и техника в рабочем состоянии.\n4.4. Составлен список на ремонт или замену плитки/мебели/оборудования (информация отправлена в чат «ремонт» или «технический»).\n4.5. Заказана или проведена дезинсекция от насекомых (в случае необходимости).\n\n5️⃣ Защита KPI (оценивает управляющий)\n\n5.1. Приём предзаказов.\n5.2. Знание актуальных акций.\n5.3. Депозитная система бара.\n5.4. Презентация бара.\n5.5. Знание формы отчёта хостес.\n5.6. Проведение собеседований.\n5.7. Закрытие столов и предоплаты.\n5.8. Работа с кассой и депозитами в выходные.\n🚀 Как использовать КЛН в стажировке\nВ начале курса: Прочитай все пункты, чтобы понимать, к чему мы идём.\nВ каждой смене: Наставник может давать отсылки к КЛН.\nНаблюдай за наставником: Отмечай, как он выполняет те или иные пункты.\nВ конце смены: Попроси наставника предварительно оценить тебя по 2–3 пунктам.\nПеред финальной аттестацией: Повтори все пункты — это будет твой финальный экзамен.\n\n❗ Важные моменты из КЛН, которые нужно запомнить\nПро карту лояльности: Перед расчётом официант уточняет: «Вы зарегистрированы в нашей системе лояльности?» Если да — фотографирует карту. Если нет — регистрирует.\nПро предзаказы: Компании от 6 человек — обязательный предзаказ. Предзаказы отмечаются в таблице бронирования, передаются на кухню и отправляются в чат «Предзаказы».\nПро проверку предоплат: Сверка предоплат с отметками в таблицах бронирования и предоплат. Предоплаты по Eat&Split вносятся в iiko.\nПро чистоту и готовность: В 17:50 должно быть включено освещение и звук входной группы. Освещение залов должно работать корректно согласно времени суток.\n\n🤔 Вопросы для самоанализа\n\nВ конце каждого дня (или в конце стажировки) задай себе эти вопросы:\n\n1. С какими ошибками я сталкиваюсь при работе с кассой и депозитами? Записывай, чтобы не повторять.\n\n2. На какие аспекты мне нужно больше внимания или обучения? Честно отмечай слабые места и обсуждай с наставником.\n\n💡 Финальный совет\n\nКЛН — это не инструмент наказания. Это твой навигатор.\n\nОн показывает, куда двигаться, чтобы стать профессионалом. Не бойся низких оценок в начале — это нормально. Главное — видеть свои зоны роста и работать над ними.\n\nКак использовать КЛН каждый день:\n\nПеред сменой — вспомни ключевые критерии.\nВо время смены — сверяй свои действия.\nПосле смены — оцени себя по 2–3 пунктам.\nОбсуждай с наставником, что получилось, а над чем работать.\n\nЗапомни: идеальных менеджеров не бывает, но есть те, кто постоянно растёт. Стремись к 100%, но не расстраивайся, если не дотягиваешь. Главное — прогресс.\n\nТы справишься! 🔥","images":["assets/remaining-courses/guru-42932-123885-0.jpg"],"links":[{"title":"СКАЧАЙ КЛН","url":"https://docs.google.com/spreadsheets/d/19k74sIGUt0vedhwkBGlWKp8A6RRQeVz6IDJcvA-ogiQ/edit?gid=0#gid=0"}],"id":"123885"},{"title":"🎓 Портрет менеджера «Бара 90-е»","text":"Цель: понять, каким должен быть менеджер — внешне, внутренне и по ценностям.\n\nВнешний образ\n\nМенеджер «Бара 90-е» — это продолжение концепции. Он не просто надевает форму, он становится частью атмосферы.\n\nОдежда:\n\nСоответствует стилю заведения (утверждена форма либо дресс-код, отсылающий к эстетике 90-х)\nОдежда чистая, выглаженная, без пятен и заломов\nОбувь начищена\n\nАккуратность:\n\nВолосы убраны или уложены\nРуки ухоженные\nОтсутствие яркого вызывающего макияжа/аксессуаров (если это не предусмотрено концепцией)\nОтсутствие резких запахов (парфюм — нейтральный, без перегара и табака)\nНогти чистые, короткие\n\nГость должен понимать: «Это главный». Внешний вид менеджера выделяет его среди команды, но не противопоставляет ей.\n\nВнутренние качества\n\nЛидер, а не надсмотрщик\n\nМенеджер не стоит над душой и не кричит. Он ведёт за собой.\n\nКоманда видит в нём опору, а не источник стресса.\n\nВ пиковые часы он не наблюдает — он подхватывает, помогает, организует.\n\nСтрессоустойчивость и эмоциональный интеллект\n\nВ пятницу в 23:00, когда очередь на входе, на баре 20 чеков, а гость жалуется на время подачи — менеджер не паникует.\n\nОн умеет:\n\n▫ отделять эмоции гостя от личных обид\n\n▫ сохранять спокойствие (его состояние транслируется на команду)\n\n▫ быстро принимать решения в нестандартных ситуациях\n\nОтветственность и честность\n\nЕсли есть расхождение в кассе — менеджер не прячет, а ищет причину.\n\nЕсли ошибся — признаёт, разбирает, делает выводы.\n\nПонимает: его зона ответственности — это не только атмосфера, но и деньги, и безопасность.\n\nВнимание к деталям\n\nЗамечает, что на третьем столе закончились салфетки, до того как гость попросил.\n\nВидит, что бармен забыл поменять маркировку.\n\nСлышит, что музыка стала чуть громче обычного.\n\nДля него «мелочей» не существует.\n\nОбучаемость и обратная связь\n\nМенеджер знает: он не знает всего.\n\nОткрыт к критике, не защищается, когда наставник указывает на ошибку.\n\nЧитает отчёты, анализирует, спрашивает: «А почему так лучше?»\n\nУправленческая зрелость\n\nНе делает работу за подчинённых, но знает, как делать.\n\nНе перекладывает ответственность.\n\nУмеет делегировать и доверять, но при этом контролировать результат.\nЦенности и убеждения менеджера\nЧто менеджер НЕ должен делать (анти-портрет)\nЦели менеджера\n\nОперационные цели (на смену)\n\nБезупречная готовность: к 18:00 всё должно быть идеально\nВыполнение плана продаж: знает план и работает на его выполнение\nСоблюдение стандартов: ни одного нарушения в сервисе, чистоте, кассовой дисциплине\nНоль конфликтов: предотвращать или решать на ранней стадии\nЧистое закрытие: отчёты без ошибок, касса сходится, зал готов к следующему дню\n\nУправленческие цели (на месяц/квартал)\n\nРазвитие команды: видит, кто может вырасти, наставляет, даёт обратную связь\nСтабильность KPI: стабильно держать оценку по КЛН не ниже 85%\nСнижение текучки: через справедливое отношение, понятные задачи и уважение\nУвеличение среднего чека: через грамотную работу официантов с акциями и картой лояльности\n\nЛичные цели (развитие)\n\nСтать управляющим (для кого-то — следующая ступень)\nМастерство переговоров: работа со сложными гостями и конфликтами\nФинансовая грамотность: от кассовых отчётов до понимания P&L заведения\nЭкспертность в сервисе: стать тем, к кому приходят учиться","images":["assets/remaining-courses/guru-42932-125255-0.jpg","assets/remaining-courses/guru-42932-125255-1.jpg","assets/remaining-courses/guru-42932-125255-2.jpg","assets/remaining-courses/guru-42932-125255-3.jpg"],"links":[],"id":"125255"},{"title":"🎓 Смена 1. «Че здесь происходит ваще?» — Погружение в проект","text":"Цель: создать полное понимание работы заведения и ответить на вопрос «что здесь происходит вообще?».\n\n👋 Твой первый день\n\nСегодня ты начинаешь путь в команду менеджеров. Твоя задача — не управлять, а смотреть, слушать и запоминать. Бар — это живой организм, и чтобы им управлять, нужно сначала понять, как он дышит.\n\n📋 Что ты делаешь сегодня\n17:00 - Приходишь на стажировку (если есть мероприятия — приходим раньше)\n17:45 — Посещаешь наше общее собрание персонала. Знакомишься с командой смены: официанты, бармены, хостес, охрана, уборщицы. Наблюдаешь, как проходит собрание, какие вопросы поднимаются.\n📖 Знакомишься с брендом и концепцией «Бар 90-е». Это не просто бар — это машина времени.\n🎯 Изучаешь обязанности менеджера по стандарту работы (кратко, без деталей — основная задача: понять масштаб ответственности).\n🗺️ Ознакомление с пространством заведения:\n\n▫ Входная группа (главный вход, служебный вход)\n\n▫ Гардероб\n\n▫ Зона хостес\n\n▫ Зал (основные зоны, VIP, фотозоны)\n\n▫ Барная стойка\n\n▫ Кухня (без входа, просто расположение)\n\n▫ Туалеты\n\n▫ Технические помещения (склады, раздевалка, комната персонала)\n\n📍 Выучить адрес, номер телефона, Wi-Fi заведения (гостевой и служебный).\n🔔 Подписаться на Instagram, Telegram-канал заведения и канал Операционного Директора.\n🚶 Изучение основных маршрутов сотрудников:\n\n▫ Вход сотрудников осуществляется через главный вход, который одновременно является зоной «суточного поста». Здесь ведется контроль времени прихода/ухода и досмотр персонала.\n\n▫ Официанты — от кухни/бара к столам, по определенным проходам.\n\n▫ Бармены — за стойкой, выход в зал при необходимости.\n\n▫ Хостес — от входа к столам и обратно.\n\n▫ Охрана — точка входа, патрулирование зала.\n\n✅ Задание на вечер\n\nВыучить как свои пять пальцев:\n\nАдрес заведения\nНомер телефона бара\nWi-Fi пароль (гостевой и служебный)\nПодписаться на Instagram и Telegram-канал заведения\nПодписаться на канал Операционного Директора\n\n💡 Финальный совет на смену\n\nСегодня ты не управляешь — ты впитываешь. Смотри, слушай, запоминай. Каждый сотрудник, каждая зона, каждый маршрут — часть большой системы. Чтобы управлять системой, нужно сначала понять, как она устроена.\n\nЗавтра — знакомство с функционалом каждой должности. Отдохни и наберись сил. 🔥","images":["assets/remaining-courses/guru-42932-123841-0.jpg"],"links":[],"id":"123841"},{"title":"🎓 Смена 2. Знакомство с функционалом должностей и оргструктурой","text":"Цель: получить полное понимание структуры и взаимодействия всех подразделений.\n\n👋 Твой второй день\n\nВчера ты узнал, что здесь происходит вообще. Сегодня ты знакомишься с каждым подразделением — кто за что отвечает, как они взаимодействуют между собой и какую роль в этой системе играет менеджер.\n\nТвоя задача — не просто запомнить названия должностей, а понять логику работы каждого звена.\n\n👮 Входная группа (охрана, суточный пост)\n\nКто это: охрана (в зале), суточный пост\n\nЛокация: зона главного входа. Персонал заходит также через главный вход. Суточный пост контролирует вход/выход сотрудников и гостей (в будни).\n\nЧто они делают:\n\nКонтроль порядка и безопасности:\n\n▫ Охрана следит за порядком в зале, обеспечивает безопасность гостей и сотрудников.\n\n▫ Решает конфликтные ситуации. Если что-то пошло не так — охрана твой первый союзник.\n\nПроверка времени прихода/ухода персонала:\n\n▫ Суточный пост досматривает сотрудников при входе и выходе, фиксирует время прихода/ухода (ТУРВ).\n\n▫ Это твой помощник в контроле дисциплины.\n\nФейсер (в будние дни):\n\n▫ В будние дни суточный пост выполняет функции фейсера — контролирует вход гостей, досмотр гостей и сотрудников.\n\nКак взаимодействуешь ты:\n\nСверяешься с суточным постом по явке сотрудников.\nОхрана — твой первый канал связи при конфликтах или нарушении порядка.\nЕсли на входе проблемы с гостями — идёшь к охране или суточному посту.\n🧥 Гардероб\n\nКто это: гардеробщик (при наличии). В отсутствие — суточный пост.\n\nЧто они делают:\n\nПринимает верхнюю одежду гостей.\nВыдаёт номерок или браслет согласно номеру на вешалке.\nПоддерживает чистоту и порядок в гардеробной зоне.\n\nКак взаимодействуешь ты:\n\nКонтролируешь, что гардероб работает и порядок соблюдается.\nЕсли гардеробщика нет — знаешь, что эту зону контролирует суточный пост.\n\n💁 Зона хостес\n\nКто это: хостес / администратор. Первое лицо, которое встречает гостя.\n\nЧто они делают:\n\nВедут учёт всех броней, входящих заявок, предоплат. Это твоя основная рабочая таблица.\nЗнают схему зала, расположение всех столов, VIP-зон, свободных мест.\nПонимают условия входа гостей (платный/бесплатный), знают актуальные акции.\nПринимают депозиты, оформляют предоплаты, выдают фишки по акциям.\n\nКак взаимодействуешь ты:\n\nРаботаешь с хостес в течение всей смены: проверяешь брони, помогаешь с рассадкой.\nВ пиковые часы подхватываешь хостес, если она не справляется.\nКонтролируешь, что все предоплаты внесены в таблицы и в iiko.\n👨‍🍳 Официанты\n\nКто это: команда зала. Главные носители сервиса.\n\nЧто они делают:\n\nВстреча гостей, приём заказов, подача блюд и напитков, уборка посуды.\nРабота с отзывами, продажи.\nСоблюдение стандартов сервиса (как подают, как убирают, как общаются).\nВзаимодействие с баром, кухней, хостес (передают заказы, забирают готовое, синхронизируют подачу).\n\nКак взаимодействуешь ты:\n\nКонтролируешь работу официантов: скорость, качество, соблюдение стандартов.\nПомогаешь решать сложные вопросы с гостями.\nПроверяешь знание акций и меню.\n🍸 Бармены\n\nКто это: команда барной стойки. Сердце напитков.\n\nЧто они делают:\n\nЗнают базовые процессы барной станции, как организована работа.\nВзаимодействуют с официантами: принимают заказы, отдают напитки, следят за очередностью.\nКонтролируют чистоту стойки, маркировку продукции, остатки напитков.\n\nКак взаимодействуешь ты:\n\nКонтролируешь чистоту барной стойки и наличие маркировки.\nСледишь за скоростью отдачи напитков в пиковые часы.\nРешаешь вопросы по остаткам и депозитам (бармен фотографирует остатки и отправляет в чат).\n🍳 Кухня\n\n🍳 Кухня\n\nКто это: повара, шеф. Там, где рождаются блюда.\n\nЧто они делают:\n\nОбеспечивают основные принципы работы: процесс приготовления, организация раздачи.\nКоммуницируют с залом по времени и качеству блюд.\nСоблюдают базовые требования к отдаче: внешний вид блюда, время приготовления, чистота тарелок.\n\nНормативы времени приготовления (запомни):\n\nХолодные закуски: до 7 минут.\nСалаты: 10–12 минут.\nГорячие закуски: до 15 минут.\nГорячие блюда: 20–40 минут.\n\nКак взаимодействуешь ты:\n\nКонтролируешь время приготовления через iiko.\nКоммуницируешь с шефом или поварами при задержках.\nПроверяешь внешний вид блюд перед подачей (чистота тарелки, аккуратность выкладки).\n\n🧹 Клининг (уборка)\n\nКто это: уборщицы.\n\nЧто они делают:\n\nОтвечают за зоны: зал, туалеты, входная зона, барная стойка.\nСоблюдают стандарты чистоты: что должно быть вымыто, протёрто, пополнено (бумага, мыло, салфетки).\nВзаимодействуют с менеджером смены, получают задачи, отчитываются о выполнении.\n\nКак взаимодействуешь ты:\n\nСтавишь задачи уборщицам (что нужно сделать, в какой зоне).\nКонтролируешь выполнение и качество.\nПроверяешь туалеты и зал на чистоту в течение смены.\n🏢 Оргструктура заведения\n\nКто кому подчиняется и по каким вопросам:\n\n1️⃣Управляющий👉\n\n👉2️⃣ Менеджер смены:\n\nОфицианты (сервис, гости)\nБармены (бар, напитки)\nХостес (вход, брони, предоплаты)\nОхрана (безопасность, порядок)\nУборщицы (чистота, расходники)\n\nОтдельно:\n\nБренд-шеф → повара (по кухне)\nБар-менеджер → бармены (по бару, закупкам)\n\nЗапомни: менеджер смены — главный в зале. К тебе приходят со всеми вопросами. Если не знаешь ответа — обращайся к управляющему.\n\nПостановка и выполнение задач в Todoist\n\nВсе задачи от Операционного директора незамедлительно вносятся в Todoist. Это обязательный инструмент планирования для руководителей.\n\nПравила:\n\nЗадача зафиксирована в Todoist — значит, она принята в работу\nВыполнение задач — без напоминаний\nЕсли поручение касается одного бара, информацию фиксируют все руководители\nНевыполнение, задержки и игнорирование — дисциплинарные меры и штрафы\nРегулярные встречи с Операционным директором\n\nРаз в две недели каждый руководитель обязан записаться на встречу с Операционным директором.\n\nСсылка для записи: ЗАПИШИСЬ\n\nЧто обсуждать:\n\nИтоги работы за период\nТекущие проблемы и сложности\nПланы и задачи\nЛичное развитие\nПредставительские столы\n\nЗапомни номера столов для важных гостей:\n\n111: Генеральный директор\n222: Арт-директор\n333: Операционный директор\n444: Бар-менеджер\n555: Управляющий Химки\n777: Директор по маркетингу\n888: Управляющая Пушкино\n999: Бренд-шеф\n1000: Менеджеры\n1001: Охрана\n1002: Арт-персонал\n\nОтдельно (пробиваются на любой стол):\n\nШарымов Дмитрий\nМоскалев Александр\n📋 Что ты делаешь сегодня\n\nВ течение смены:\n\n1. Подойди к каждому подразделению и понаблюдай за их работой. Задай вопросы:\n\nОхране: «Какие ситуации у вас самые частые?»\nХостес: «Покажи, как работает таблица бронирования».\nОфицианту: «Как ты взаимодействуешь с баром?»\nБармену: «Как ты получаешь заказы от официантов?»\nПовару: «Как понять, что блюдо готово?»\nУборщице: «Какие зоны ты убираешь в течение смены?»\n\n2. Запомни схему подчинения: кто кому докладывает, к кому обращаться по каким вопросам.\n\n3. Выучи нормативы времени приготовления.\n\n✅ Задание на вечер\n\n1. В уме проговори функции каждого подразделения.\n\n2. Вспомни, как они взаимодействуют между собой.\n\n3. Выучи нормативы времени приготовления блюд.\n\n💡 Финальный совет на смену\n\nСегодня ты не управляешь — ты знакомишься. Но уже завтра эти знания начнут работать. Чем лучше ты понимаешь, кто чем занимается и как они взаимодействуют, тем легче тебе будет ставить задачи, контролировать и решать проблемы.\n\nЗапомни главное: менеджер — это не тот, кто делает всё сам. Менеджер — это тот, кто организует работу других.\n\nЗавтра — работа хостес в депозитный день. Готовься к погружению в финансы на входе. 🔥","images":["assets/remaining-courses/guru-42932-123876-0.jpg"],"links":[{"title":"ЗАПИШИСЬ","url":"https://calendar.app.google/6YAJXV64VVHSbaQAA"}],"id":"123876"},{"title":"🎓 Смена 3–4. Работа хостес в депозитный день","text":"Цель: разобраться с финансовыми потоками на входе — депозиты, предоплаты, работа хостес.\n\n🎁 Акции бара — инструмент привлечения и удержания гостей\n\nС первого дня ты должен знать все акции, которые действуют в баре. Акции — это не просто «скидки». Это инструменты, которые работают на разные задачи:\n\nПривлечение новых гостей\nУдержание постоянных\nЗагрузка в тихие дни\nДополнительные продажи\n\nАкции делятся на постоянные и временные. Постоянные ты учишь наизусть. Временные — отслеживаешь в рабочих чатах и на собраниях.\n\n📌 Постоянные акции бара\n\n1. Скидка на день рождения 50%\n\nУсловия: Именинник + компания\nВремя действия: ПН–ВС, 18:00–06:00\nДетали: Пакетные предложения (3 варианта на выбор) с определенным ассортиментом.\n\n2. Аркадий угощает\n\nУсловия: Гость получает фишку на входе.\nВремя действия: Воскресенье, весь день до 23:00.\nДетали: Фишку можно обменять на коктейль у бармена. Акция не распространяется на участников квизов, конкурсов и других специальных мероприятий.\n\n3. Всё меню от 390 ₽\n\nУсловия: Любое блюдо из меню.\nВремя действия: ПН–ВС, весь день.\nДетали: Фиксированная цена 390 ₽. Дешевле, чем дома!\n\n4. Дети кушают бесплатно\n\nУсловия: Ребёнок до 14 лет.\nВремя действия: ВС–ЧТ, 18:00–22:00.\nДетали: Одно блюдо из меню за 390 ₽ (на одного взрослого — один ребенок). Акция действует только в указанные часы.\n\n5. Караоке за наш счёт\n\nУсловия: При бронировании стола.\nВремя действия: ВС–ЧТ, весь день.\nДетали: Гости поют бесплатно всю ночь. Работает на загрузку в будние дни.\n\n⚠️ Важные нюансы акций, которые нужно знать\nСкидка на день рождения 50%:\n\n▫ Гость должен предъявить документ (паспорт) с датой рождения.\n\n▫ Внести предоплату минимум за 3 дня, в 100% объеме.\n\n▫ Акция действует в день рождения (плюс/минус неделя).\n\nАркадий угощает:\n\n▫ Фишки выдаются на входе (передаем фишки хостес к 18:00).\n\n▫ Фишку гость отдаёт бармену в обмен на коктейль.\n\n▫ Акция НЕ распространяется на участников квизов, конкурсов и специальных мероприятий.\n\n▫ Менеджер контролирует, что фишек достаточно и они выдаются по правилам.\n\nВсё меню по 390 ₽:\n\n▫ Это НЕ означает, что все блюда стоят 390 ₽. Большая часть блюд порционных, именно по такой цене.\n\nДети кушают бесплатно:\n\n▫ Возраст ребёнка — до 14 лет включительно.\n\n▫ Одно блюдо из меню за 390 ₽ на одного взрослого — один ребёнок.\n\n▫ Временной коридор — с 18:00 до 22:00, не весь день.\n\nКараоке за наш счёт:\n\n▫ Гость должен забронировать стол.\n\n▫ Пение бесплатно всю ночь (за исключением позиций из крейзи меню).\n\n💳 Карта лояльности — важный инструмент удержания гостя\n\nС первого дня ты должен понимать: карта лояльности — это не просто скидка. Это способ сказать гостю «мы тебя ценим» и сделать так, чтобы он возвращался снова и снова.\n\nЧто такое карта постоянного гостя?\n\nЭто программа лояльности, которая позволяет гостю копить бонусы с каждого посещения и тратить их на следующие визиты. Карта работает на привязанном номере телефона.\n\nКлючевые цифры, которые нужно знать наизусть:\n\nКэшбэк с каждого посещения: до 10% от чека (бонусами)\nМаксимум оплаты бонусами: до 50% от суммы чека\nБонус за оформление карты: 390 рублей в подарок\nСрок действия бонусов: 6 месяцев с даты начисления\nОбновление статуса: каждые 6 месяцев\n\nУровни карты:\n\nУровень 1: Сумма трат от 0 до 20 000 ₽ → начисление бонусами 5%\nУровень 2: Сумма трат от 20 000 до 50 000 ₽ → начисление бонусами 7%\nУровень 3: Сумма трат от 50 000 ₽ → начисление бонусами 10%\n\nВажно запомнить:\n\nЕсли за 6 месяцев сумма трат оказывается ниже порога уровня — статус снижается.\nБонусы сгорают через 6 месяцев после даты начисления.\n1 бонус = 1 рубль.\n🔄 Как гость может пользоваться картой\n\n1. При оплате заказа гость говорит официанту, что у него есть карта.\n\n2. Гость показывает электронную карту.\n\n3. Официант фотографирует и отправляет в рабочий чат.\n\n4.  Менеджер вносит номер в iiko, система показывает баланс бонусов и доступный процент списания.\n\n5. Остаток оплачивается любым удобным способом.\n\nЕсли у гостя нет карты — это возможность! Официант (или менеджер) предлагает оформить: «Хотите оформить карту постоянного гостя? При первом заказе получите 390 бонусов в подарок!»\n\n🔴 КРИТИЧЕСКИ ВАЖНО: Правила оплаты и закрытия столов\n\n1. Окончательный расчет и закрытие стола — ТОЛЬКО МЕНЕДЖЕР\n\nОфицианты НЕ закрывают столы. Никогда.\n\nОфициант может уточнить способ оплаты и подготовить всё для оплаты.\nНо закрытие чека, закрытие стола в iiko делает только менеджер.\n\n2. Если скидка 20% и выше — ТОЛЬКО НАЛИЧНЫЕ\n\nЭто жёсткое правило, которое нельзя нарушать.\n\nСкидка менее 20%: любой способ оплаты (наличные, карта).\nСкидка 20% и выше: ТОЛЬКО НАЛИЧНЫЕ.\n\nКак объяснить гостю:\n\n«По условиям нашей программы лояльности, при скидке 20% и выше оплата возможна только наличными. Если вам удобнее оплатить картой, скидка, к сожалению, не применится — вы сможете воспользоваться ей в следующий раз».\n\n3. Алгоритм расчёта (запомни последовательность)\n\nГость попросил счет.\nОфициант уточняет: «У вас есть карта постоянного гостя?» (если есть — фото в чат, если нет — предлагает оформить).\nОфициант уточняет способ оплаты: «Наличными или картой?»\nЕсли скидка 20% и выше, а гость хочет картой — официант объясняет правило, зовёт менеджера.\nМенеджер подходит к столу, проводит финальный расчёт.\nМенеджер закрывает чек и стол в iiko.\nМенеджер контролирует, что стол подготовлен к следующей посадке.\n\n4. Что делать, если гость настаивает на оплате картой при скидке 20%+\n\nНе спорь.\nВежливо объясни правило ещё раз.\nПредложи альтернативу: скидка не применяется, оплата картой по полной стоимости.\nВ сложных ситуациях — зови управляющего.\n🤝 Что делает хостес с акциями и картой лояльности\nАркадий угощает: Выдаёт фишки гостям на входе. Контролирует, что фишка выдана одному гостю (не компании). Следит, чтобы фишки не забирали участники мероприятий.\nСкидка на день рождения: Проверяет документы при необходимости, отмечает в брони, что гость именинник.\nКарта лояльности: Предлагает оформить карту гостям на входе. Объясняет условия (390 бонусов, копить до 10%, тратить до 50%).\nВсё меню по 390 ₽: Информирует гостей при входе об акции.\nДети кушают бесплатно: Информирует гостей с детьми, уточняет возраст.\nКараоке за наш счёт: Предлагает бронирование, объясняет условия.\n✅ Задание на два дня\n\n1.     Работай на хостес — принимай гостей, депозиты, работай с таблицами.\n\n2.    Выучи все постоянные акции — условия, время действия, нюансы.\n\n3.    Выучи карту лояльности — уровни (5%/7%/10%), 390 бонусов при оформлении, списание до 50%, срок 6 месяцев.\n\n4.    Выучи правила оплаты — стол закрывает только менеджер, скидка 20%+ = только наличные.\n\n5. Освой алгоритм работы с предоплатами (5 шагов).\n\n6. Пойми, чем менеджер помогает хостес в депозитный день.\n\n💡 Финальный совет на два дня\n\nТы сейчас в самом сердце финансовых потоков бара. Депозиты, предоплаты, акции, карта лояльности, правила оплаты — это не просто «работа на входе». Это фундамент, на котором держится экономика вечера.\n\nЗапомни главное:\n\nКаждая предоплата должна быть внесена в таблицу и в iiko.\nАкции нужно знать наизусть.\nКарту лояльности нужно знать наизусть.\nСтол закрывает только менеджер.\nСкидка 20% и выше — только наличные.\n\nДальше — смена 5–6: работа с кассой и финансовыми процедурами. Готовься! 🔥","images":["assets/remaining-courses/guru-42932-123881-0.jpg"],"links":[],"id":"123881"},{"title":"🎓 Смена 5–6. Работа с кассой и финансовыми процедурами","text":"Цель: базово разобраться в финансовой дисциплине заведения.\n\n👋 Пятый и шестой дни\n\nТы уже освоил работу на входе — депозиты, предоплаты, акции, карту лояльности. Теперь ты погружаешься в финансовую дисциплину заведения. Это один из самых ответственных блоков.\n\nЗа два дня ты разберёшься:\n\nКак устроены кассовые смены\nКак сдаётся выручка\nКакие финансовые отчёты ведёт менеджер\nКак работает сверка план-факт\nКак вести графики персонала (плановый и фактический)\n💰 1. Работа с кассой — общие принципы\n\nКассовая дисциплина (ККД) — это ежедневная сверка всех финансовых операций. Всё должно сходиться.\n\nОсновные элементы кассовой работы:\n\nКассовая смена: Период работы кассы от открытия до закрытия.\nТерминал: Устройство для безналичной оплаты. В конце смены сверяется с iiko.\niiko: Наша система учёта заказов и платежей. Все операции проходят через неё.\nКассовый отчёт: Документ, который формируется в iiko и отражает все операции за смену.\nСейф: Место хранения наличности. Доступ только у менеджера и управляющего.\n🔄 2. Алгоритм работы с кассой в течение смены\n\nВ течение смены менеджер:\n\nКонтролирует, что все платежи проходят через iiko.\nПроверяет, что официанты не принимают оплату самостоятельно (только менеджер закрывает столы).\nСледит за наличием сдачи в кассе.\nФиксирует все расходы (чеки с подписью «Оплачено»).\n🔒 3. Закрытие кассовой смены (алгоритм)\n\n1. Снять Z-отчёт с терминала (сумма безналичных платежей).\n\n2. Снять отчёт из iiko (общая сумма выручки за смену).\n\n3. Сверить данные терминала и iiko — они должны совпадать.\n\n4. Пересчитать наличность в кассе.\n\n5. Заполнить кассовый отчёт (форма утверждена управляющим).\n\n6. Подготовить выручку к сдаче (упаковать, заполнить инкассационную ведомость).\n\n7. Сдать выручку в сейф (по регламенту).\n\n📊 4. Сверка план-факт\n\nПлан-факт — это сравнение запланированных показателей с фактическими.\n\nВыручка за смену: План (по плану продаж) vs Факт (по отчёту iiko) → Отклонение (+/-)\nРасходы: План (по бюджету) vs Факт (по чекам) → Отклонение (+/-)\nКоличество гостей: План (по броням) vs Факт (по факту) → Отклонение (+/-)\n\nЧто делать при расхождениях:\n\nЕсли выручка меньше плана — проанализировать причины (мало гостей, низкий средний чек, ошибки в учёте).\nЕсли расходы выше бюджета — проверить чеки, возможно, были незапланированные закупки.\nЕсли есть несоответствия в отчётах — искать ошибку в iiko или терминале.\n\nВажно: несоответствия в отчётах удерживаются из зарплаты менеджера. Будь внимателен.\n\n📋 5. Финансовые отчёты менеджера\n\nКаждый день после закрытия смены менеджер формирует отчёт в группу «manager». Все списания подтверждаются фото и фиксируются в чатах.\n\n📅 6. Графики персонала — плановый и фактический\n\nПлановый график\n\nСоставляется: раз в месяц, до 25 числа.\nУчитывает: генеральную уборку, инвентаризацию, праздничные/депозитные дни, арт-программу.\nКорректируется: при увольнении или принятии сотрудников.\n\nАлгоритм составления:\n\n1. Взять арт-программу на следующий месяц.\n\n2. Определить депозитные дни и праздники — туда ставим больше сотрудников.\n\n3. Учесть дни генеральной уборки и инвентаризации.\n\n4. Распределить официантов, хостес, уборщиц по сменам.\n\n5. Согласовать с управляющим.\n\n6. Опубликовать в группе «Штат».\n\nФактический график\n\nВедётся: ежедневно.\nЗаполняется: в конце смены согласно ТУРВ (Табель учёта рабочего времени).\nКонтролирует: суточный пост — досматривает персонал, проверяет корректность заполнения ТУРВ.\n\nАлгоритм работы с фактическим графиком:\n\n1. В конце смены заполнить фактический график согласно ТУРВ.\n\n2. ТУРВ убрать в офис.\n\n3. 1-го числа месяца распечатать фактический график на ресепшн.\n\n4. Персонал проверяет свои смены, корректировка — только карандашом, с подписью.\n\n5. До 3-го числа персонал обязан проверить и расписаться.\n\n6. График скидывается в электронном виде в группу «Штат».\n\n7. До 5-го числа табель с подписями сдаётся управляющему.\n\nВажные правила:\n\nПосле 5-го числа изменения в табеле не принимаются.\nОпоздание до 2 часов без согласования = минус полная смена.\nУход раньше при отсутствии гостей: до 00:30 — 0,5 смены.\n💸 7. Расходы и выплаты, которые отражает менеджер\n\nВ ежедневном отчёте менеджер отражает:\n\nЧаевые артистов: фиксируются по фото в рабочем чате Техническая - \"крейзи\".\nЧаевые бара: фиксируются по фото в рабочем чате бар - \"чаевые\".\nЧаевые сервиса: распределяются по регламенту, фото в чат \"сервак\".\nПродления: 25 000 ₽ за 30 мин, оплата персоналу (менеджер — 1 500, ведущий — 2 000, официант — 1 000, бармен — 1 000, уборщица — 1 000).\nМотивации: за продажу мерча (футболки, цветы, Бьюти наборы), столы.\nВыдачи уборщицам: за дополнительные смены или задачи.\nКрейзи / DJ: каждый чек фотографируется, в конце смены отчёт: дата, продано песен, чаевые, к выдаче.\n📋 8. Что ты делаешь сегодня и завтра\nРабота с кассой: участвуешь в открытии и закрытии кассовой смены под наблюдением наставника.\nСверка отчётов: сверяешь терминал с iiko, заполняешь кассовый отчёт.\nСдача выручки: учишься упаковывать и сдавать выручку.\nГрафики: изучаешь плановый график на месяц, участвуешь в заполнении фактического графика.\nОтчёт менеджера: под руководством наставника составляешь отчёт в группу «manager».\n\nФишки для персонала — что мы предлагаем команде\nДоплата за выслугу: от 1 года работы — 1 000 ₽\nСкидка на напитки и кальяны: 40% для сотрудников\nАлкоголь в выходной: до 2 позиций по согласованию\nTeam building: Регулярные мероприятия для команды\nСкидки на свои мероприятия: Сотрудники получают скидки на билеты\n«Приведи друга»: Бонус до 10 000 ₽ за приведённого сотрудника\nКарьерный рост: Возможность роста внутри сети\nМотивация за продажи: подробности по ссылке (в шпаргалке есть гиперссылка)\n✅ Задание на два дня\n\n1. Участвуй в открытии и закрытии кассовой смены.\n\n2.  Сверь терминал и iiko.\n\n3.  Заполни кассовый отчёт под руководством наставника.\n\n4.  Изучи плановый график.\n\n5.  Участвуй в заполнении фактического графика.\n\n6.  Составь отчёт в группу «manager» с помощью наставника\n\n💡 Финальный совет на два дня\n\nТы сейчас в самом сердце финансового управления баром. Касса, отчёты, графики — это инструменты, которые позволяют держать руку на пульсе заведения.\n\nЗапомни главное:\n\nСтол закрывает только менеджер — это твоя зона ответственности.\nСверка терминала и iiko — делай это внимательно, ошибки стоят денег.\nГрафики — основа дисциплины.\nОтчёт в «manager» — твой инструмент коммуникации с руководством.\n\nДальше — смена 7: управление сменой в сопровождении наставника. Готовься к первому выходу у руля! 🔥","images":["assets/remaining-courses/guru-42932-123895-0.jpg"],"links":[],"id":"123895"},{"title":"🎓 Смена 7. Управление сменой в сопровождении наставника","text":"Цель: участие в полноценной смене под наблюдением — первый опыт управления.\n\n👋 Седьмой день — твой первый день у руля\n\nПоздравляю! Ты прошёл 6 дней стажировки. Ты познакомился с заведением, изучил функции всех подразделений, разобрался с депозитами и предоплатами, освоил кассовую дисциплину и работу с графиками.\n\nСегодня ты проходишь полноценную смену в роли менеджера под наблюдением наставника.\n\n📋 Что ты делаешь сегодня\n17:00 — Начало рабочего дня. Большой обход зала. (Наставник наблюдает, проверяет вместе с тобой). Если есть мероприятия (концерты, ДР бара, отчетный концерты И так далее, приходим раньше).\n17:45 — Проводишь собрание с персоналом. (Наставник подстраховывает, дополняет)\n18:00 — Открытие заведения для гостей. (Наставник контролирует)\n18:05 — Снятие приветственного сторис. (Наставник проверяет качество)\n18:00–21:00 — Обработка ТБ заявок (входящие брони). (Наставник помогает, объясняет нюансы)\nВ течение смены — Управление персоналом, контроль сервиса, атмосферы. (Наставник наблюдает, даёт советы)\nКонец смены — Закрытие смены, отчёты. (Наставник проверяет, подписывает)\nПосле смены — Итоговый разбор с наставником. (Наставник даёт обратную связь)\n1. Начало смены: большой обход (17:00)\n\nТвоя задача: проверить готовность зала к открытию.\n\nЧек-лист большого обхода:\n\nВходная группа: Чистота, работа охраны, наличие расходников (браслеты, фишки, карты).\nГардероб: Чистота, порядок, наличие номерков.\nЗона хостес: Готовность зоны, наличие таблиц, ручек, телефона, анкет, брошюр, раскрасок.\nЗал: Чистота столов, стульев, пола. Сервировка (тарелки, приборы, салфетки, тейбл-тенты). Декор, фотозоны.\nБар: Чистота стойки, маркировка, наличие льда, лимона, расходников.\nТуалеты: Чистота, наличие бумаги, мыла, освежителя.\nТехнические помещения: Порядок, чистота.\n\nЧто делать, если нашли недочёты:\n\nЗафиксировать в задачник.\nНа собрании озвучить и поставить задачи ответственным.\nПроконтролировать устранение до 18:00.\n\n2. Собрание с персоналом (17:45)\n\nТвоя задача: провести собрание, задать настрой на вечер, донести важную информацию.\n\nСтруктура собрания:\n\n1. Приветствие: Добрый вечер, команда!\n\n2. Итоги прошлой смены: Что было хорошо, что можно улучшить (кратко).\n\n3. План на сегодня: Количество броней, депозитные столы, VIP-гости, особые пожелания.\n\n4. Акции и мероприятия: Какие акции действуют сегодня, что важно помнить.\n\n5. Задачи по зонам: Кто за какие столы отвечает (расписать согласно ТБ броней).\n\n6. Отзывы и конкурсы: Напоминание про «Честный отзыв», план по отзывам.\n\n7. Общие вопросы: Есть ли вопросы у команды?\n\nВажно: Говори уверенно, чётко. Не читай с листа. Улыбайся, задавай тон на позитив.\n\n3. Открытие заведения (18:00)\n\nТвоя задача: убедиться, что всё готово, и дать команду на открытие.\n\nЧек-лист перед открытием:\n\nВсе столы засервированы.\nСотрудники на местах.\nМузыка включена, освещение настроено.\nХостес готова встречать гостей.\nОхрана на входе.\n\nПосле открытия:\n\n18:05 — снять приветственное сторис (атмосфера зала, пустые красивые столы, яркий уголок).\nРазместить в Instagram и Telegram-канал заведения.\n4. Обработка ТБ заявок (18:00–21:00)\n\nТвоя задача: контролировать обработку входящих броней.\n\nЧто нужно сделать:\n\nУбедиться, что хостес обрабатывает все заявки.\nВ 21:00 собрать итог: сколько обработано, сколько не обработано, причина.\n\nЕсли заявок много — помогаешь хостес.\n\n5. Управление сменой: контроль в течение вечера\n\nТвоя задача: держать руку на пульсе. Ты организуешь процесс.\n\nЧто ты контролируешь:\n\nПосадка гостей: Хостес рассаживает согласно броням, ты проверяешь, что VIP-гости на своих местах.\nСервис: Официанты соблюдают стандарты: приветствие, подача, чек-бэк, уборка.\nАтмосфера: Музыка, освещение, чистота в зале, настроение гостей.\nСкорость: Время подачи напитков и блюд, работа кухни и бара.\nДисциплина: Сотрудники на местах, никто не курит толпой, все в форме.\n\nПериодичность:\n\nКаждый час — обход зала по малой восьмёрке (быстрый осмотр всех зон).\nКаждые 2–3 часа — снятие сторис (атмосфера, гости, яркие моменты).\n6. Работа с гостями и сбор ОС\n\nТвоя задача: собирать обратную связь от гостей.\n\nЧто спрашивать:\n\nВсё ли нравится по еде и напиткам?\nКак атмосфера?\nКак сервис?\nКак арт-программа (если есть)?\n\nКуда фиксировать:\n\nВ заметки (основные моменты).\nВ отчёт по смене (в конце).\n\nВажно: если гость жалуется — выслушай, поблагодари, извинись, позови наставника, если нужно.\n\n7. Работа в пиковые часы\n\nПиковые часы: пятница, суббота, воскресенье, праздники — 23:00–03:00.\n\nТвоя задача в пик:\n\nБыть в зале, видеть всё, что происходит.\nПомогать хостес, если очередь на входе.\nКонтролировать, что официанты не заваливаются.\nСледить за чистотой столов.\nРешать конфликтные ситуации (с подключением охраны, если нужно).\n\nСоветы для работы в пик:\n\nНе суетись — спокойствие менеджера передаётся команде.\nПриоритизируй: сначала безопасность, потом сервис, потом отчёты.\n8. Закрытие смены\n\nТвоя задача: принять смену у всех подразделений, сдать отчёты, подготовить зал к следующему дню.\n\nЧек-лист закрытия:\n\n1. Принять смену у официантов, барменов, хостес, уборщицы, гардеробщика.\n\n2. Заполнить фактический график согласно ТУРВ.\n\n3. Снять отчёты с терминала и iiko.\n\n4. Заполнить кассовый отчёт, сверить с терминалом.\n\n5. Сдать выручку (в сейф или инкассаторам).\n\n6. Провести большой обход зала — проверить выключенное оборудование, чистоту.\n\n7. Проверить фотоотчёт чистого зала.\n\n8. Написать общий отчёт по смене в группу «manager».\n\n9. Сообщить управляющему о завершении смены.\n\n9. Структура итогового отчёта в группу «manager»\n\nФормат отчёта (пример):\n\nСмена: 24.03.2026\n\nМенеджер: [Имя]\n\n📊 ВЫРУЧКА:\n\nНаличные: 250 000 ₽\n\nБезнал: 200 000 ₽\n\nИтого: 450 000 ₽\n\nСр. чек на баре: 2 300 ₽\n\n⏰ ПРОДЛЕНИЯ:\n\n1 час → 25 000 ₽\n\n🎁 ПРОДАЖИ:\n\nМишка - 10 000\n\nНабор Б - 2 600\n\nЦарский - 5 000\n\n📝 ОТЗЫВЫ И ПРОИСШЕСТВИЯ:\n\nЖалоба на время подачи горячего — решено комплиментом от заведения\nКонфликт на входе — решено охраной\n\n✅ ВСЁ ХОРОШО, СМЕНА СДАНА\n\n10. Итоговый разбор с наставником\n\nЧто обсуждаете:\n\nЧто получилось хорошо?\nКакие были сложности?\nКак ты справлялся?\nЧто можно улучшить?\nКакие зоны роста?\n\nТвоя задача:\n\nСлушать внимательно, не перебивать.\nНе оправдываться.\nЗаписать зоны роста.\nПоблагодарить наставника.\n✅ Задание на смену\n\n1. Проведи большой обход в 17:00 и зафиксируй недочёты.\n\n2. Проведи собрание в 17:45 (наставник подстрахует).\n\n3. Сними приветственное сторис в 18:05.\n\n4. Контролируй обработку заявок.\n\n5. Делай обходы зала каждый час.\n\n6. Снимай сторис каждые 2–3 часа.\n\n7. Собери ОС от гостей (минимум 3–5 отзывов за вечер).\n\n8. Закрой смену по чек-листу.\n\n9. Напиши отчёт в группу «manager».\n\n10. Пройди разбор с наставником.\n\n💡 Финальный совет на смену\n\nСегодня ты доказываешь, что готов к самостоятельной работе. Не бойся ошибаться — наставник рядом. Но старайся делать всё сам. Именно так приходит уверенность.\n\nЗапомни главное:\n\nБольшой обход в 17:00 — залог готовности зала.\nСобрание в 17:45 — задаёт настрой на вечер.\nКонтроль — это не беготня, а организация процесса.\nЗакрытие — делай чисто, чтобы утром всё было готово.\nОтчёт — пиши честно, это твой инструмент коммуникации с руководством.\n\nИ помни: гость не знает, что ты стажёр. Для него ты — менеджер. Действуй соответственно.\n\nТы справишься! После этой смены ты будешь готов к самостоятельной работе. 🔥\n\nПосле смены 7 — финальный этап стажировки завершён. Следующие 2 месяца — обучение в режиме работы под наблюдением, освоение еженедельных и ежемесячных задач, работа с КЛН менеджера.\n\nТы в команде! 💪","images":["assets/remaining-courses/guru-42932-123880-0.jpg"],"links":[],"id":"123880"},{"title":"🎓Аттестация менеджера","text":"Цель: понять, как проходит аттестация, что оценивается и к чему готовиться.\n\nСтруктура аттестации: Аттестация состоит из двух частей: теоретическая и практическая.\n\nТеоретическая часть — знание стандартов\n\nМенеджер обязан знать и понимать:\n\n1. Стандарты сервиса\n\nСкорость обслуживания (этапы, нормативы, контроль)\nРабота при высокой загрузке (приоритизация, перераспределение ресурсов)\nВзаимодействие с гостями (решение конфликтов, работа с жалобами)\n\n2. Операционные процессы\n\nОткрытие/закрытие смены\nКонтроль кассовой дисциплины\nРабота с бронями и посадкой\nВзаимодействие с кухней и баром\n\n3. Управление персоналом\n\nПостановка задач официантам\nКонтроль выполнения\nОбучение и адаптация новых сотрудников\nРабота с мотивацией команды\n\n4. Продукт\n\nЗнание меню кухни и бара\nАпселл и рекомендации\nКонтроль качества отдачи\nПрактическая часть — управление сменой\n\nМенеджер проходит проверку в реальной смене, где оценивается:\n\n1. Контроль зала\n\nРавномерная загрузка официантов\nОтсутствие «потерянных» столов\nСоблюдение стандартов сервиса\n\n2. Скорость обслуживания\n\nВлияние на время принятия заказа\nВлияние на скорость отдачи\nМинимизация задержек\n\n3. Работа при высокой загрузке\n\nБыстрое принятие решений\nПомощь официантам в пиковые часы\nПерераспределение зон ответственности\n\n4. Работа с гостями\n\nЛичное взаимодействие с проблемными столами\nПредотвращение конфликтов\nПовышение лояльности гостей\nАналитика и влияние на показатели\n\nМенеджер должен уметь не просто «держать смену», а управлять цифрами.\n\n1. Основные метрики\n\nВыручка смены\nСредний чек\nКоличество гостей\nОборачиваемость столов\n\n2. Умение анализировать\n\nПричины роста/падения показателей\nВлияние загрузки на сервис\nВлияние команды на результат\n\n3. Управленческие действия\n\nЧто делать при низкой посадке\nКак увеличивать средний чек\nКак ускорять оборачиваемость\nЭто закрывает твою боль: «проблемы с аналитикой и влиянием на посещаемость». Менеджер обязан не просто видеть цифры, а уметь на них влиять.﻿\nУправление командой\nИтоговая оценка\nПо результатам аттестации менеджеру выставляется оценка по пяти критериям:\nРезультаты аттестации","images":["assets/remaining-courses/guru-42932-125256-0.jpg","assets/remaining-courses/guru-42932-125256-1.jpg","assets/remaining-courses/guru-42932-125256-2.jpg","assets/remaining-courses/guru-42932-125256-3.jpg"],"links":[],"id":"125256"},{"title":"🎓KPI и бонусная система менеджера","text":"Цель: понять, из чего складывается доход менеджера и за что начисляются бонусы.\n\nЦель системы KPI\nВыполнение и перевыполнение плана выручки заведения\nОбеспечение безупречной кассовой дисциплины\nПоддержание высоких стандартов сервиса и атмосферы\nРазвитие управленческих навыков и вовлечённости в результат\nСнижение операционных ошибок и повышение эффективности смены\nСтруктура дохода\nДоход менеджера состоит из:\nБонусная система\nЕжедневный бонус за перевыполнение плана выручки\n\nКритерии начисления:\n\nВыручка подтверждена отчётами iiko\nСмена закрыта корректно, без кассовых расхождений\nОтчёт в группе «manager» сдан вовремя\nМесячный KPI-бонус\nНачисляется по итогам месяца при выполнении совокупности показателей.\nБонус за продления\n\nКритерии начисления:\n\nПродление согласовано с управляющим\nФакт продления зафиксирован в отчёте\nОплата от гостя получена\nОбщие условия начисления бонусов\n\nБонусы выплачиваются при соблюдении следующих условий:\n\nСмена сдана в соответствии с регламентом\nВсе отчёты (кассовый, в группу «manager», графики) сданы вовремя и без ошибок\nОтсутствуют подтверждённые жалобы гостей на работу менеджера\nСоблюдены стандарты внешнего вида и трудовой дисциплины\nКассовая дисциплина не нарушена\n❗ Важно: При выявлении нарушений (расхождение в кассе, некорректное закрытие стола, нарушение правил оплаты скидок, сдача отчёта не в срок) соответствующий бонус может быть снижен или аннулирован по решению управляющего.\n\nКонтроль и учёт\nВсе показатели фиксируются в системе iiko, рабочих чатах и отчётах\nОтветственный за контроль — управляющий\nКонтрольный лист наблюдения (КЛН) заполняется управляющим по результатам проверок\nСпорные ситуации разбираются индивидуально управляющим на основании документальных подтверждений","images":["assets/remaining-courses/guru-42932-125279-0.jpg","assets/remaining-courses/guru-42932-125279-1.jpg","assets/remaining-courses/guru-42932-125279-2.jpg","assets/remaining-courses/guru-42932-125279-3.jpg"],"links":[],"id":"125279"}],"outline":[{"type":"lesson","title":"🎓КЛН МЕНЕДЖЕРА — Контрольный лист наблюдения","lessonIndex":0},{"type":"lesson","title":"🎓 Портрет менеджера «Бара 90-е»","lessonIndex":1},{"type":"lesson","title":"🎓 Смена 1. «Че здесь происходит ваще?» — Погружение в проект","lessonIndex":2},{"type":"test","title":"Тест к смене 1"},{"type":"lesson","title":"🎓 Смена 2. Знакомство с функционалом должностей и оргструктурой","lessonIndex":3},{"type":"test","title":"Тест к смене 2"},{"type":"lesson","title":"🎓 Смена 3–4. Работа хостес в депозитный день","lessonIndex":4},{"type":"test","title":"Тест к сменам 3-4"},{"type":"lesson","title":"🎓 Смена 5–6. Работа с кассой и финансовыми процедурами","lessonIndex":5},{"type":"test","title":"Тест к сменам 5-6"},{"type":"lesson","title":"🎓 Смена 7. Управление сменой в сопровождении наставника","lessonIndex":6},{"type":"test","title":"Тест к смене 7"},{"type":"lesson","title":"🎓Аттестация менеджера","lessonIndex":7},{"type":"lesson","title":"🎓KPI и бонусная система менеджера","lessonIndex":8}],"testIds":["105287","105288","105289","105290","105291"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
