insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-53164','course','Тренажер Про 90-е',null,'{"id":"guru-53164","title":"Тренажер Про 90-е","shortTitle":"Тренажер Про 90-е","coverLabel":"Тренажер Про 90-е","description":"Тренировка знаний о баре «90-е».","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Тренажер Про 90 е","text":"","images":[],"links":[{"title":"Видео к уроку","url":"https://cdn-local.my.service.guru/uploads/lesson/document_file/135378/RackMultipart20260820-2017065-pjgf64.html"}],"id":"135378"}],"outline":[{"type":"lesson","title":"Тренажер Про 90 е","lessonIndex":0}],"testIds":[]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
